package com.morongaming.forsakenrealm;
import android.content.Context;import android.graphics.*;import android.view.*;
/** Live navigation over the original clean castle artwork; no reference-image buttons. */
final class LandingView extends View {
 interface Host{void select(int action);String version();}
 private final Host host;private final MenuFrame f=new MenuFrame();private final boolean credits;private float downX,downY;
 LandingView(Context c,Host h,boolean credits){super(c);host=h;this.credits=credits;setContentDescription(credits?"Forsaken Realm credits. Moron Gaming. Back to main.":"Forsaken Realm main menu: Play, Settings, Store, Credits, Exit.");}
 protected void onDraw(Canvas c){f.begin(c,this);f.paint.setColor(0x66000000);c.drawRect(0,0,960,540,f.paint);f.text(c,"FORSAKEN REALM",32,62,36,650,0xfff3e5c8);f.text(c,"FORGED IN WAR. RULED BY THE RUTHLESS.",35,86,12,600,0xffc5a36b);f.text(c,"v"+host.version(),838,40,15,95);
 if(credits){f.panel(c,220,140,520,292,false);f.text(c,"A GAME BY",397,185,18,200);f.text(c,"MORON GAMING",285,242,37,410);f.text(c,"The people behind the realm",326,282,18,365);f.text(c,"Thank you for exploring Forsaken Realm.",275,333,18,420);f.text(c,"Your stories shape what comes next.",296,367,17,390);f.panel(c,32,460,250,52,false);f.text(c,"<  BACK TO MAIN",56,493,19,210);}else{String[] labels={"PLAY","SETTINGS","STORE","CREDITS","EXIT"},sub={"ENTER THE REALM","ADJUST YOUR EXPERIENCE","BROWSE THE MARKET","THE PEOPLE BEHIND THE REALM","LEAVE THE GAME"};for(int i=0;i<5;i++){float y=118+i*61;f.panel(c,32,y,300,54,i==0);icon(c,i,60,y+27);f.text(c,labels[i],100,y+23,21,218);f.text(c,sub[i],101,y+42,10,216,0xffb9b0a0);}f.panel(c,32,448,460,62,false);f.text(c,"EXPLORE  ·  SURVIVE  ·  CONQUER",51,475,20,420);f.text(c,"One realm. Your own story.",53,495,13,410,0xffc5b79e);}c.restore();}
 private void icon(Canvas c,int i,float x,float y){Paint p=f.paint;p.setColor(0xffd7bd83);p.setStrokeWidth(2);p.setStyle(Paint.Style.STROKE);if(i==0){c.drawLine(x-12,y+13,x+12,y-13,p);c.drawLine(x-12,y-13,x+12,y+13,p);c.drawLine(x-14,y+7,x-6,y+15,p);c.drawLine(x+6,y+15,x+14,y+7,p);}else if(i==1){c.drawCircle(x,y,11,p);c.drawCircle(x,y,4,p);for(int a=0;a<8;a++){double r=a*Math.PI/4;c.drawLine(x+(float)Math.cos(r)*12,y+(float)Math.sin(r)*12,x+(float)Math.cos(r)*17,y+(float)Math.sin(r)*17,p);}}else if(i==2){c.drawRect(x-14,y-10,x+14,y+12,p);c.drawLine(x-14,y-1,x+14,y-1,p);c.drawRect(x-3,y-2,x+3,y+5,p);}else if(i==3){c.drawRect(x-14,y-12,x+14,y+12,p);c.drawLine(x,y-12,x,y+12,p);c.drawLine(x-10,y-6,x-4,y-6,p);c.drawLine(x+4,y-6,x+10,y-6,p);}else{c.drawRect(x-11,y-15,x+11,y+15,p);c.drawCircle(x+5,y,1,p);}p.setStyle(Paint.Style.FILL);}
 public boolean performClick(){super.performClick();return true;}
 public boolean onTouchEvent(MotionEvent e){float x=f.x(e.getX()),y=f.y(e.getY());if(e.getActionMasked()==MotionEvent.ACTION_DOWN){downX=x;downY=y;return true;}if(e.getActionMasked()!=MotionEvent.ACTION_UP)return true;if(Math.hypot(x-downX,y-downY)>14)return true;performClick();if(credits){if(x>=32&&x<=282&&y>=460&&y<=512)host.select(5);}else if(x>=32&&x<=332&&y>=118&&y<417&&(y-118)%61<=54)host.select((int)((y-118)/61));return true;}
}
